import{_ as t,o,c as s,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"Folding Ranges","description":"","frontmatter":{},"headers":[],"relativePath":"folding/index.md","filePath":"folding/index.md"}'),i={name:"folding/index.md"};function d(n,e,c,l,r,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="folding-ranges" tabindex="-1">Folding Ranges <a class="header-anchor" href="#folding-ranges" aria-label="Permalink to &quot;Folding Ranges&quot;">​</a></h1><p>LazyVerilog gives your editor folds for common SystemVerilog structure. They come from a fast scan of the tokens, so they work while you type. Single-line constructs never fold.</p><table tabindex="0"><thead><tr><th>Fold</th><th>Covers</th></tr></thead><tbody><tr><td>Module</td><td><code>module</code> through <code>endmodule</code>, header included</td></tr><tr><td>Header lists</td><td>the <code>#(...)</code> parameter list and the <code>(...)</code> port list</td></tr><tr><td>Declarations</td><td>a run of consecutive declarations</td></tr><tr><td>Imports</td><td>a run of consecutive <code>import</code> lines</td></tr><tr><td>Comments</td><td>consecutive own-line comments, and block comments</td></tr><tr><td>Preprocessor</td><td>each branch of <code>\`ifdef</code>, <code>\`else</code>, <code>\`endif</code></td></tr><tr><td>Blocks</td><td><code>begin</code>/<code>end</code>, <code>case</code>, <code>generate</code>, <code>fork</code>/<code>join</code>, <code>function</code>, <code>task</code>, <code>class</code>, <code>constraint</code>, <code>covergroup</code>, <code>clocking</code>, <code>typedef enum</code>/<code>struct</code>/<code>union</code></td></tr></tbody></table><h2 id="declaration-runs" tabindex="-1">Declaration runs <a class="header-anchor" href="#declaration-runs" aria-label="Permalink to &quot;Declaration runs&quot;">​</a></h2><p>A run folds when its lines start with a keyword or type: <code>logic</code>, <code>wire</code>, <code>reg</code>, <code>var</code>, <code>integer</code>, <code>localparam</code>, <code>input</code>, and so on. Any other statement ends the run.</p><div class="language-systemverilog vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">systemverilog</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">logic</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> a;</span></span>
<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">logic</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> b;</span></span>
<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">assign</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> b </span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> a;   </span><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">// ends the run</span></span>
<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">logic</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> c;</span></span>
<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">logic</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> d;</span></span></code></pre></div><p>This gives two folds, <code>a</code>/<code>b</code> and <code>c</code>/<code>d</code>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>A declaration that starts with a user-defined type (<code>state_e state_q;</code>) does not fold. It looks the same as an instance to a token scan, so LazyVerilog does not guess.</li><li>An instance does not fold as a whole. Its <code>#(...)</code> override list folds on its own.</li><li>The parameter list and the port list share the <code>)(</code> line, so Neovim merges them into one header fold.</li></ul><h2 id="turn-it-off" tabindex="-1">Turn it off <a class="header-anchor" href="#turn-it-off" aria-label="Permalink to &quot;Turn it off&quot;">​</a></h2><p>Set <code>[folding].enable = false</code> in <code>lazyverilog.toml</code>, and <code>folding = false</code> in the Neovim <a href="./../installation/neovim"><code>setup()</code></a> to stop the editor asking. See <a href="./../lsp/#folding-ranges">LSP features</a>.</p>`,11)])])}const g=t(i,[["render",d]]);export{k as __pageData,g as default};
